"use client"

import * as React from "react"
import { Label } from "@/components/ui/label"
import { Input } from "@/components/ui/input"
import { SearchableSelect } from "@/components/ui/select"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Collapsible, CollapsibleTrigger, CollapsibleContent } from "@/components/ui/collapsible"
import { Separator } from "@/components/ui/separator"
import { Badge } from "@/components/ui/badge"
import DependentDropdown from "./dependent-dropdown"
import { ChevronDown, Settings2, Type, Hash, Menu, CheckSquare, ListChecks } from "lucide-react"
import type { FieldType } from "@/generated/prisma/enums"

type SpecField = {
  id: string
  key: string
  label: string
  type: FieldType
  required?: boolean
  config?: Record<string, unknown>
}

type Option = { label: string; value: string; qty?: number; price?: number }

function formatIDR(value: unknown): string {
  const num = typeof value === "number" ? value : Number(value ?? 0)
  if (!Number.isFinite(num)) return String(value ?? "")
  return new Intl.NumberFormat("id-ID", { style: "currency", currency: "IDR", currencyDisplay: "code", minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(num)
}

function fieldTypeIcon(type: FieldType) {
  switch (type) {
    case "TEXT": return <Type className="h-3 w-3" />
    case "TEXTAREA": return <ListChecks className="h-3 w-3" />
    case "NUMBER": return <Hash className="h-3 w-3" />
    case "DROPDOWN": return <Menu className="h-3 w-3" />
    case "CHECKBOX": return <CheckSquare className="h-3 w-3" />
    default: return <Type className="h-3 w-3" />
  }
}

function fieldTypeLabel(type: FieldType): string {
  switch (type) {
    case "TEXT": return "Teks"
    case "TEXTAREA": return "Teks Panjang"
    case "NUMBER": return "Angka"
    case "DROPDOWN": return "Pilihan"
    case "CHECKBOX": return "Centang"
    default: return type
  }
}

function CheckboxRow({
  option,
  namePrefix,
  fieldKey,
  defaultChecked,
  defaultQty,
}: {
  option: Option
  namePrefix: string
  fieldKey: string
  defaultChecked: boolean
  defaultQty: number
}) {
  const [qty, setQty] = React.useState(defaultQty)
  const [checked, setChecked] = React.useState(defaultChecked)

  const price = option.price ?? 0
  const subtotal = (qty || 0) * price

  return (
    <tr className="border-b border-slate-100 last:border-0 transition-colors hover:bg-slate-50/50">
      <td className="py-2.5 pr-4 align-top">
        <div className="flex items-start gap-3 pt-0.5">
          <input
            type="checkbox"
            name={`${namePrefix}spec_${fieldKey}__${option.value}`}
            defaultChecked={checked}
            onChange={(e) => setChecked(e.target.checked)}
            id={`${namePrefix}spec_${fieldKey}__${option.value}`}
            className="mt-0.5 h-4 w-4 rounded border-slate-300 text-primary focus:ring-primary transition-colors"
          />
          <Label htmlFor={`${namePrefix}spec_${fieldKey}__${option.value}`} className="cursor-pointer font-normal text-sm leading-snug text-slate-700">
            {option.label}
            {price > 0 && (
              <span className="block text-xs text-slate-400 mt-0.5">
                @ {formatIDR(price)}
              </span>
            )}
          </Label>
        </div>
      </td>
      <td className="py-2.5 pr-4 align-top">
        {typeof option.qty === "number" && option.qty > 0 ? (
          <Input
            name={`${namePrefix}spec_${fieldKey}__${option.value}__qty`}
            type="number"
            className="h-8 w-24 border-slate-200 focus:border-primary focus:ring-primary/20"
            placeholder="Qty"
            value={qty || ""}
            onChange={(e) => setQty(Number(e.target.value))}
            disabled={!checked}
          />
        ) : null}
      </td>
      <td className="py-2.5 text-sm align-top pt-3">
        {checked && subtotal > 0 ? (
          <span className="font-medium text-slate-900">{formatIDR(subtotal)}</span>
        ) : (
          <span className="text-slate-400">&mdash;</span>
        )}
      </td>
    </tr>
  )
}

export default function QuotationItemSpecs({
  dependsOnName,
  branchId,
  defaultProductId,
  defaultValues,
  namePrefix = "row_",
  containerId,
}: {
  dependsOnName: string
  branchId?: string
  defaultProductId?: string
  defaultValues?: Record<string, unknown>
  namePrefix?: string
  containerId?: string
}) {
  const [productId, setProductId] = React.useState<string | undefined>(defaultProductId)
  const [fields, setFields] = React.useState<SpecField[]>([])
  const [optionsMap, setOptionsMap] = React.useState<Record<string, Option[]>>({})
  const [open, setOpen] = React.useState(true)
  const internalContainerId = React.useId().replace(/:/g, "_")
  const actualContainerId = containerId || internalContainerId

  const fetchSpecs = React.useCallback(async (pid: string) => {
    if (!pid) return
    const params = new URLSearchParams({ productId: pid })
    if (branchId) params.set("branchId", branchId)
    const res = await fetch(`/api/product-specs?${params.toString()}`)
    if (!res.ok) return
    const data = (await res.json()) as { fields: SpecField[]; options: Record<string, Option[]> }
    setFields(data.fields)
    setOptionsMap(data.options || {})
  }, [branchId])

  React.useEffect(() => {
    const scopeEl = actualContainerId ? document.getElementById(actualContainerId) : undefined
    const el = scopeEl ? scopeEl.querySelector<HTMLInputElement>(`input[name="${dependsOnName}"]`) : document.querySelector<HTMLInputElement>(`input[name="${dependsOnName}"]`)
    const initial = el?.value || defaultProductId || ""
    if (initial) {
      setProductId(initial)
      fetchSpecs(initial)
    }
    const handler = (e: Event) => {
      const ev = e as CustomEvent<{ name: string; value: string }>
      if (!ev.detail) return
      const { name, value } = ev.detail
      if (name === dependsOnName) {
        const elLocal = scopeEl ? scopeEl.querySelector<HTMLInputElement>(`input[name="${dependsOnName}"]`) : document.querySelector<HTMLInputElement>(`input[name="${dependsOnName}"]`)
        const v = elLocal?.value || value || ""
        setProductId(v || undefined)
        if (v) fetchSpecs(v)
      }
    }
    window.addEventListener("docFieldChange", handler as EventListener)
    return () => window.removeEventListener("docFieldChange", handler as EventListener)
  }, [dependsOnName, branchId, defaultProductId, fetchSpecs, actualContainerId])

  if (!productId) return null

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="md:col-span-2" id={actualContainerId}>
      <Card className="border border-slate-200/80 shadow-sm overflow-hidden">
        <CollapsibleTrigger asChild>
          <div className="cursor-pointer">
            <CardHeader className="py-3 px-4 pb-2 flex flex-row items-center gap-3">
              <div className="flex items-center gap-2">
                <div className="h-6 w-6 rounded-md bg-primary/10 flex items-center justify-center">
                  <Settings2 className="h-3.5 w-3.5 text-primary" />
                </div>
                <CardTitle className="text-sm font-semibold text-slate-900">Spesifikasi Produk</CardTitle>
              </div>
              <div className="ml-auto flex items-center gap-2">
                {fields.length > 0 && (
                  <Badge variant="secondary" className="text-[10px] font-medium">
                    {fields.length} field{fields.length > 1 ? "s" : ""}
                  </Badge>
                )}
                <ChevronDown className={`h-4 w-4 text-slate-400 transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
              </div>
            </CardHeader>
          </div>
        </CollapsibleTrigger>
        <CollapsibleContent>
          <Separator />
          <CardContent className="pt-4 px-4 pb-4 space-y-4">
            {fields.length === 0 ? (
              <div className="text-center py-6">
                <div className="h-10 w-10 rounded-full bg-slate-50 flex items-center justify-center mx-auto mb-3">
                  <Settings2 className="h-5 w-5 text-slate-300" />
                </div>
                <p className="text-sm text-slate-400">Tidak ada spesifikasi untuk produk ini</p>
              </div>
            ) : (
              <>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4">
                  {fields.filter((s) => s.type !== "CHECKBOX").map((s) => {
                    const def = defaultValues ? defaultValues[`spec_${s.key}`] : undefined

                    if (s.type === "TEXT") {
                      return (
                        <div key={s.id} className="space-y-1.5">
                          <div className="flex items-center gap-2">
                            <Label className="text-xs font-medium text-slate-600">{s.label}{s.required ? " *" : ""}</Label>
                            <Badge variant="outline" className="text-[10px] h-4 px-1.5 py-0 font-normal">{fieldTypeLabel(s.type)}</Badge>
                          </div>
                          <Input name={`${namePrefix}spec_${s.key}`} defaultValue={typeof def === "string" ? def : ""} className="h-9 border-slate-200 focus:border-primary focus:ring-primary/20" />
                        </div>
                      )
                    }
                    if (s.type === "TEXTAREA") {
                      return (
                        <div key={s.id} className="space-y-1.5 md:col-span-2">
                          <div className="flex items-center gap-2">
                            <Label className="text-xs font-medium text-slate-600">{s.label}{s.required ? " *" : ""}</Label>
                            <Badge variant="outline" className="text-[10px] h-4 px-1.5 py-0 font-normal">{fieldTypeLabel(s.type)}</Badge>
                          </div>
                          <textarea name={`${namePrefix}spec_${s.key}`} className="border-slate-200 text-sm rounded-lg border bg-white px-3 py-2.5 shadow-sm outline-none focus-visible:ring-2 focus-visible:ring-primary/20 focus-visible:border-primary w-full min-h-20 transition-all" defaultValue={typeof def === "string" ? def : ""} />
                        </div>
                      )
                    }
                    if (s.type === "NUMBER") {
                      return (
                        <div key={s.id} className="space-y-1.5">
                          <div className="flex items-center gap-2">
                            <Label className="text-xs font-medium text-slate-600">{s.label}{s.required ? " *" : ""}</Label>
                            <Badge variant="outline" className="text-[10px] h-4 px-1.5 py-0 font-normal">{fieldTypeLabel(s.type)}</Badge>
                          </div>
                          <Input name={`${namePrefix}spec_${s.key}`} type="number" defaultValue={typeof def === "number" ? String(def) : ""} className="h-9 border-slate-200 focus:border-primary focus:ring-primary/20" />
                        </div>
                      )
                    }
                    if (s.type === "DROPDOWN") {
                      const cfg = (s.config ?? {}) as { options?: Option[]; source?: Record<string, unknown> }
                      const dyn = optionsMap[s.key]
                      const options = dyn ?? (Array.isArray(cfg.options) ? cfg.options : [])

                      if (cfg.source) {
                        const src = cfg.source as any
                        const filterRaw = src["filter"] as unknown
                        const filters = Array.isArray(filterRaw)
                          ? (filterRaw as Array<Record<string, unknown>>).map((x) => ({
                              dependsOn: typeof x["dependsOn"] === "string" ? (x["dependsOn"] as string) : "",
                              field: typeof x["field"] === "string" ? (x["field"] as string) : "",
                            })).filter((it) => it.dependsOn && it.field)
                          : (() => {
                              const dependsOn = typeof (filterRaw as Record<string, unknown>)?.["dependsOn"] === "string" ? ((filterRaw as Record<string, unknown>)["dependsOn"] as string) : ""
                              const fieldSrc = typeof (filterRaw as Record<string, unknown>)?.["field"] === "string" ? ((filterRaw as Record<string, unknown>)["field"] as string) : ""
                              return (dependsOn && fieldSrc) ? [{ dependsOn, field: fieldSrc }] : []
                            })()

                        const sourceObj = {
                          mode: src["mode"],
                          key: src["key"],
                          table: src["table"],
                          labelField: src["labelField"] || "name",
                          valueField: src["valueField"] || "id",
                          filter: (filters.length > 1 ? filters : (filters[0] ?? undefined)) as any,
                        }

                        return (
                          <div key={s.id} className="space-y-1.5">
                            <div className="flex items-center gap-2">
                              <Label className="text-xs font-medium text-slate-600">{s.label}{s.required ? " *" : ""}</Label>
                              <Badge variant="outline" className="text-[10px] h-4 px-1.5 py-0 font-normal">{fieldTypeLabel(s.type)}</Badge>
                            </div>
                            <DependentDropdown
                              name={`${namePrefix}spec_${s.key}`}
                              label={s.label}
                              required={s.required}
                              options={options}
                              defaultValue={typeof def === "string" ? def : ""}
                              source={sourceObj}
                              branchId={branchId}
                              containerId={actualContainerId}
                            />
                          </div>
                        )
                      }

                      return (
                        <div key={s.id} className="space-y-1.5">
                          <div className="flex items-center gap-2">
                            <Label className="text-xs font-medium text-slate-600">{s.label}{s.required ? " *" : ""}</Label>
                            <Badge variant="outline" className="text-[10px] h-4 px-1.5 py-0 font-normal">{fieldTypeLabel(s.type)}</Badge>
                          </div>
                          <SearchableSelect
                            name={`${namePrefix}spec_${s.key}`}
                            placeholder="Pilih..."
                            options={options.map((o) => ({ label: o.label, value: o.value }))}
                            defaultValue={typeof def === "string" ? def : ""}
                            emitChangeEvent={true}
                            containerId={actualContainerId}
                            required={s.required}
                          />
                        </div>
                      )
                    }
                    return null
                  })}
                </div>
                {fields.filter((s) => s.type === "CHECKBOX").map((s) => {
                  const def = defaultValues ? defaultValues[`spec_${s.key}`] : undefined
                  const cfg = (s.config ?? {}) as { options?: Option[] }
                  const opts = Array.isArray(cfg.options) ? cfg.options : []
                  const selectedArr = Array.isArray(def) ? (def as unknown[]).map(String) : []
                  return (
                    <div key={s.id} className="space-y-2">
                      <div className="flex items-center gap-2">
                        <Label className="text-xs font-medium text-slate-600">{s.label}{s.required ? " *" : ""}</Label>
                        <Badge variant="outline" className="text-[10px] h-4 px-1.5 py-0 font-normal">{fieldTypeLabel(s.type)}</Badge>
                      </div>
                      <div className="rounded-lg border border-slate-200 overflow-hidden">
                        <table className="w-full text-sm">
                          <thead>
                            <tr className="bg-slate-50/80 border-b border-slate-200">
                              <th className="text-left py-2.5 px-3 font-medium text-slate-500 text-xs w-[55%]">Item</th>
                              <th className="text-left py-2.5 px-3 font-medium text-slate-500 text-xs w-24">Qty</th>
                              <th className="text-right py-2.5 px-3 font-medium text-slate-500 text-xs">Sub Total</th>
                            </tr>
                          </thead>
                          <tbody>
                            {opts.map((o, i) => {
                              const checked = selectedArr.includes(String(o.value))
                              const qtyDefKey = `spec_${s.key}__${o.value}__qty`
                              const qtyDefRaw = defaultValues ? defaultValues[qtyDefKey] : undefined
                              const qtyVal = typeof qtyDefRaw === "number" ? qtyDefRaw : 0

                              return (
                                <CheckboxRow
                                  key={i}
                                  option={o}
                                  namePrefix={namePrefix}
                                  fieldKey={s.key}
                                  defaultChecked={checked}
                                  defaultQty={qtyVal}
                                />
                              )
                            })}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  )
                })}
              </>
            )}
          </CardContent>
        </CollapsibleContent>
      </Card>
    </Collapsible>
  )
}